<label>استان<select name="province_id"><option value="">مکان ثبت نشده</option><?php foreach($provinces as $p): ?><option value="<?= $this->h($p['id']) ?>" <?= $selectedProvince===$p['id']?'selected':'' ?>><?= $this->h($p['name']) ?></option><?php endforeach; ?></select></label><label>شهرستان<select name="county_id"><option value="">فقط استان / شهرستان نامشخص</option><?php foreach($places as $p):if(!$p['parent_id']){continue;} ?><option data-parent="<?= $this->h($p['parent_id']) ?>" value="<?= $this->h($p['id']) ?>" <?= $selectedCounty===$p['id']?'selected':'' ?>><?= $this->h($p['name']) ?></option><?php endforeach; ?></select></label>
